
"""Comparison of FCS files generated by PyFCS and JFCS.

Both files are read without modification. Stored geometry is compared directly,
and membership values are calculated with the same PyFCS evaluator to isolate
differences between the two geometries. The Java membership evaluator is not run.

Examples (from the project root):
    python -m Source.test.compare_fcs_engines
    python -m Source.test.compare_fcs_engines --demo
    python -m Source.test.compare_fcs_engines --pyfcs "py.fcs" --jfcs "java.fcs"
    python -m Source.test.compare_fcs_engines --pair Partition "py.fcs" "java.fcs"
"""

import argparse
import csv
import json
import math
import sys
import time
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

import numpy as np


# Project root, independent of the current working directory.
ROOT = Path(__file__).resolve().parents[2]

if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from Source.input_output.InputFCS import InputFCS


# Reference FCS pairs stored alongside the test modules.
FIXTURES = Path(__file__).resolve().parent / "fixtures"


class ComparisonInputError(Exception):
    """Invalid FCS data or incompatible comparison settings."""
    pass


def unique_prototypes(space, origin):
    """Index representatives by label, rejecting duplicates and invalid coordinates."""
    result = {}

    for proto in space.prototypes:
        label = str(proto.label)

        if label in result:
            raise ComparisonInputError(
                f"{origin}: duplicate category label {label!r}"
            )

        positive = np.asarray(proto.positive, dtype=float)

        if positive.shape != (3,) or not np.all(np.isfinite(positive)):
            raise ComparisonInputError(
                f"{origin}: invalid representative of {label!r}"
            )

        result[label] = proto

    return result


def configuration_differences(py, java, tolerance):
    """List incompatible FCS configuration parameters without raising errors."""
    problems = []

    if py.color_space != java.color_space:
        problems.append(
            f"model: {py.color_space} versus {java.color_space}"
        )

    if (py.disjoint, py.covering) != (java.disjoint, java.covering):
        problems.append(
            f"typology: {(py.disjoint, py.covering)} "
            f"versus {(java.disjoint, java.covering)}"
        )

    if not np.allclose(
        py.reference_domain.bounds,
        java.reference_domain.bounds,
        atol=tolerance,
        rtol=0
    ):
        problems.append("different reference-domain bounds")

    for key in ("lambda1", "lambda2"):
        if abs(getattr(py, key) - getattr(java, key)) > tolerance:
            problems.append(f"different {key}")

    # Samples affect non-covering spaces only.
    if not py.covering and py.samples != java.samples:
        problems.append(
            f"non-covering samples: {py.samples} versus {java.samples}"
        )

    return problems


def check_compatible(py, java, tolerance):
    """Validate the FCS pair before comparing stored geometry or memberships."""
    problems = configuration_differences(py, java, tolerance)

    a = unique_prototypes(py, "PyFCS")
    b = unique_prototypes(java, "JFCS")

    if set(a) != set(b):
        problems.append(
            "different category names: "
            f"PyFCS-only={sorted(set(a) - set(b))}, "
            f"JFCS-only={sorted(set(b) - set(a))}"
        )

    if not a:
        problems.append("no representatives")

    if problems:
        raise ComparisonInputError(
            "Cannot compare incompatible FCS files: "
            + "; ".join(problems)
        )

    # The PyFCS label order is used for both membership vectors.
    labels = list(a)

    positive_deltas = {
        label: float(
            np.max(np.abs(a[label].positive - b[label].positive))
        )
        for label in labels
    }

    max_delta = max(positive_deltas.values())

    if max_delta > tolerance:
        raise ComparisonInputError(
            f"representative mismatch: maximum coordinate difference "
            f"{max_delta:.8g} > {tolerance:g}; top: "
            f"{sorted(positive_deltas.items(), key=lambda kv: -kv[1])[:3]}"
        )

    return labels, {
        "geometry": py.color_space,
        "disjoint": py.disjoint,
        "covering": py.covering,
        "domain": list(py.reference_domain.bounds),
        "lambda1": py.lambda1,
        "lambda2": py.lambda2,
        "samples_effective": py.samples if not py.covering else None,
        "labels": labels,
        "representatives_max_absolute_delta": max_delta,
        "raw_samples_fields": {
            "pyfcs": py.samples,
            "jfcs": java.samples
        },
        "source_formats": {
            "pyfcs": getattr(py, "source_file_format", None),
            "jfcs": getattr(java, "source_file_format", None)
        }
    }


def canonical_plane(face):
    """Normalize a plane equation so equivalent planes can be compared.

    A common normal length and sign remove arbitrary coefficient scaling.
    """
    plane = face.getPlane()

    arr = np.asarray(
        [plane.A, plane.B, plane.C, plane.D],
        dtype=float
    )

    n = float(np.linalg.norm(arr[:3]))

    if not np.all(np.isfinite(arr)) or n < 1e-12:
        raise ComparisonInputError("Invalid plane in FCS geometry")

    arr /= n

    first = next(
        (v for v in arr[:3] if abs(v) > 1e-12),
        1.0
    )

    if first < 0:
        arr = -arr

    return arr


def describe_planes(space, layer, labels):
    """Collect face counts, normalized planes and domain boundaries by color."""
    group = {
        "core": space.cores,
        "voronoi": space.prototypes,
        "support": space.supports
    }[layer]

    lookup = {p.label: p for p in group}
    result = {}

    for label in labels:
        faces = lookup[label].voronoi_volume.getFaces()

        result[label] = {
            "planes": np.asarray(
                [canonical_plane(f) for f in faces],
                dtype=float
            ).reshape(-1, 4),
            "domain_faces": sum(
                1 for f in faces if f.isDomainBoundary()
            ),
            "faces": len(faces)
        }

    return result


def count_matches(a, b, tol):
    """Count one-to-one plane matches within the coordinate tolerance."""
    unused = set(range(len(b)))
    matched = 0

    for p in a:
        if not unused:
            break

        indices = list(unused)
        deltas = np.max(np.abs(b[indices] - p), axis=1)
        ix = int(np.argmin(deltas))

        if deltas[ix] <= tol:
            unused.remove(indices[ix])
            matched += 1

    return matched


def geometry_report(py, java, labels, tol):
    """Compare stored Core, Voronoi and Support faces for every category."""
    output = {}

    for layer in ("core", "voronoi", "support"):
        first = describe_planes(py, layer, labels)
        second = describe_planes(java, layer, labels)

        rows = []

        for label in labels:
            a = first[label]
            b = second[label]

            rows.append({
                "label": label,
                "pyfcs_faces": a["faces"],
                "jfcs_faces": b["faces"],
                "pyfcs_domain_faces": a["domain_faces"],
                "jfcs_domain_faces": b["domain_faces"],
                "matching_planes": count_matches(
                    a["planes"],
                    b["planes"],
                    tol
                )
            })

        output[layer] = {
            "pyfcs_faces": sum(r["pyfcs_faces"] for r in rows),
            "jfcs_faces": sum(r["jfcs_faces"] for r in rows),
            "matching_planes": sum(r["matching_planes"] for r in rows),
            "pyfcs_domain_faces": sum(
                r["pyfcs_domain_faces"] for r in rows
            ),
            "jfcs_domain_faces": sum(
                r["jfcs_domain_faces"] for r in rows
            ),
            "by_category": rows
        }

    return output


def membership_vector(space, point, labels):
    """Return raw memberships in the common category order."""
    result = space.calculate_raw_memberships(
        point,
        input_space="MODEL",
        include_zeros=True
    )

    vec = np.asarray(
        [float(result.get(label, 0.0)) for label in labels],
        dtype=float
    )

    if not np.all(np.isfinite(vec)):
        raise ComparisonInputError(
            "Membership calculation returned NaN or Infinity"
        )

    return vec


def normalize_distribution(values):
    """Normalize partition memberships only when their sum differs from one."""
    total = float(np.sum(values))

    if total <= 1e-12 or abs(total - 1.0) <= 1e-9:
        return values

    return values / total


def winner(values, labels, tolerance=1e-12):
    """Return the highest-membership category, or None for zero membership."""
    best = float(np.max(values))

    if best <= tolerance:
        return None

    return labels[int(np.argmax(values))]


def compare_region(
    py,
    java,
    labels,
    mins,
    maxs,
    n,
    seed,
    tolerance,
    top_records,
    region
):
    """Evaluate both saved geometries at identical reproducible random points."""
    rng = np.random.default_rng(seed)
    points = rng.uniform(mins, maxs, size=(n, 3))

    stats = Counter()
    affected = Counter()

    max_diff = -1.0
    mean_diff = 0.0
    raw_sums_py = []
    raw_sums_jfcs = []
    top = []
    norm_max = 0.0

    for xyz in points:
        # Both vectors use the same evaluator; only stored geometry differs.
        a = membership_vector(py, xyz, labels)
        b = membership_vector(java, xyz, labels)

        delta = np.abs(a - b)
        d = float(np.max(delta))

        mean_diff += d

        # Count affected points and categories separately.
        if d > tolerance:
            stats["different_raw_points"] += 1

            for idx in np.where(delta > tolerance)[0]:
                affected[labels[int(idx)]] += 1

        if d > max_diff:
            max_diff = d

        if winner(a, labels) != winner(b, labels):
            stats["raw_winner_changes"] += 1

        # Application-level winner also includes overlapping-core tie breaks.
        i = py.best_prototype_index(
            xyz,
            input_space="MODEL"
        )

        j = java.best_prototype_index(
            xyz,
            input_space="MODEL"
        )

        lab_a = (
            labels[int(i)]
            if i is not None and i >= 0
            else None
        )

        lab_b = (
            labels[int(j)]
            if j is not None and j >= 0
            else None
        )

        if lab_a != lab_b:
            stats["mapping_winner_changes"] += 1

        # Normalized memberships are relevant only to partition spaces.
        if py.is_partition:
            norm_a = normalize_distribution(a)
            norm_b = normalize_distribution(b)

            nd = float(np.max(np.abs(norm_a - norm_b)))
            norm_max = max(norm_max, nd)

            if nd > tolerance:
                stats["different_normalized_points"] += 1

            raw_sums_py.append(float(np.sum(a)))
            raw_sums_jfcs.append(float(np.sum(b)))

        # Retain only the largest discrepancies for the CSV report.
        if top_records > 0 and d > tolerance:
            k = int(np.argmax(delta))

            detail = {
                "region": region,
                "x1": float(xyz[0]),
                "x2": float(xyz[1]),
                "x3": float(xyz[2]),
                "label": labels[k],
                "mu_pyfcs": float(a[k]),
                "mu_jfcs_geometry": float(b[k]),
                "absolute_difference": d,
                "winner_pyfcs": lab_a,
                "winner_jfcs_geometry": lab_b
            }

            if len(top) < top_records:
                top.append(detail)
                top.sort(
                    key=lambda x: x["absolute_difference"],
                    reverse=True
                )

            elif d > top[-1]["absolute_difference"]:
                top[-1] = detail
                top.sort(
                    key=lambda x: x["absolute_difference"],
                    reverse=True
                )

    result = {
        "region": region,
        "samples": n,
        "seed": seed,
        "raw_different_points": stats["different_raw_points"],
        "raw_different_percent": round(
            100 * stats["different_raw_points"] / n,
            5
        ),
        "raw_winner_changes": stats["raw_winner_changes"],
        "mapping_winner_changes": stats["mapping_winner_changes"],
        "max_raw_membership_difference": max_diff,
        "mean_pointwise_max_raw_difference": mean_diff / n,
        "affected_categories": dict(affected),
        "top_cases": top
    }

    if py.is_partition:
        result["normalized"] = {
            "different_points": stats["different_normalized_points"],
            "different_percent": round(
                100 * stats["different_normalized_points"] / n,
                5
            ),
            "max_difference": norm_max,
            "raw_sum_pyfcs": {
                "min": min(raw_sums_py),
                "mean": float(np.mean(raw_sums_py)),
                "max": max(raw_sums_py)
            },
            "raw_sum_jfcs_geometry": {
                "min": min(raw_sums_jfcs),
                "mean": float(np.mean(raw_sums_jfcs)),
                "max": max(raw_sums_jfcs)
            }
        }

    return result


def compare_pair(pair_name, py_path, java_path, args):
    """Load one pair and compare configuration, geometry and memberships."""
    start = time.perf_counter()

    try:
        _, py = InputFCS().read_file(str(py_path))
        _, java = InputFCS().read_file(str(java_path))

    except Exception as exc:
        raise ComparisonInputError(
            f"Failed to load FCS files for {pair_name}: {exc}"
        ) from exc

    # Configuration mismatches are validation results, not exceptions.
    differences = configuration_differences(
        py,
        java,
        args.config_tolerance
    )

    if differences:
        return {
            "pair": pair_name,
            "validation_error": (
                "Cannot compare incompatible FCS files: "
                + "; ".join(differences)
            )
        }

    labels, config = check_compatible(
        py,
        java,
        args.config_tolerance
    )

    geometry = geometry_report(
        py,
        java,
        labels,
        args.plane_tolerance
    )

    bounds = np.asarray(
        py.reference_domain.bounds,
        dtype=float
    ).reshape(3, 2)

    region_results = []

    # Compare boundary and interior regions independently.
    for region_idx, margin in enumerate(args.margins):
        mins = bounds[:, 0] + margin
        maxs = bounds[:, 1] - margin

        if np.any(mins >= maxs):
            raise ComparisonInputError(
                f"Margin {margin} is too large for domain "
                f"{bounds.tolist()}. Choose smaller --margins "
                "for LAB or restricted domains."
            )

        region = (
            "full"
            if margin == 0
            else f"margin_{margin:g}"
        )

        region_results.append(
            compare_region(
                py,
                java,
                labels,
                mins,
                maxs,
                args.points,
                args.seed + region_idx,
                args.tolerance,
                args.top,
                region
            )
        )

    return {
        "pair": pair_name,
        "pyfcs_file": str(py_path.resolve()),
        "jfcs_file": str(java_path.resolve()),
        "configuration": config,
        "geometry": geometry,
        "regions": region_results,
        "identical_stored_planes": all(
            all(
                r["pyfcs_faces"]
                == r["jfcs_faces"]
                == r["matching_planes"]
                for r in layer["by_category"]
            )
            for layer in geometry.values()
        ),
        "elapsed_seconds": round(
            time.perf_counter() - start,
            3
        )
    }


def main(argv=None):
    """Run the selected comparisons and save their reports."""
    parser = argparse.ArgumentParser(
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter
    )

    # Select bundled examples, a single pair or several named pairs.
    inp = parser.add_mutually_exclusive_group()

    inp.add_argument(
        "--demo",
        action="store_true",
        help="Compare the two bundled real RGB pairs"
    )

    inp.add_argument(
        "--pyfcs",
        type=Path,
        help="Single PyFCS FCS file (requires --jfcs)"
    )

    parser.add_argument(
        "--jfcs",
        type=Path,
        help="Single JFCS FCS file (requires --pyfcs)"
    )

    parser.add_argument(
        "--pair",
        nargs=3,
        metavar=("NAME", "PYFCS", "JFCS"),
        action="append",
        help="Compare a named pair; may be repeated"
    )

    parser.add_argument(
        "--points",
        type=int,
        default=1500,
        help="Points PER margin per pair (default 1500)"
    )

    parser.add_argument(
        "--margins",
        default="0,25,50,80",
        help="Domain margin per axis, comma-separated"
    )

    parser.add_argument(
        "--seed",
        type=int,
        default=6123108
    )

    parser.add_argument(
        "--tolerance",
        type=float,
        default=1e-5,
        help="Membership difference tolerance"
    )

    parser.add_argument(
        "--config-tolerance",
        type=float,
        default=1e-6
    )

    parser.add_argument(
        "--plane-tolerance",
        type=float,
        default=1e-5
    )

    parser.add_argument(
        "--top",
        type=int,
        default=25,
        help="Worst points to save per region"
    )

    # Reports are saved within Source/test.
    parser.add_argument(
        "--report-dir",
        type=Path,
        default=ROOT / "Source" / "test" / "test_reports"
    )

    parser.add_argument(
        "--strict-geometry",
        action="store_true",
        help="Return a failure code if saved plane sets differ"
    )

    parser.add_argument(
        "--strict-membership",
        action="store_true",
        help="Return a failure code if ANY raw membership differs"
    )

    parser.add_argument(
        "--allow-winner-differences",
        action="store_true",
        help="Do not fail if winners differ (differences are still reported)"
    )

    args = parser.parse_args(argv)

    # Validate sampling and tolerance settings before reading files.
    if (
        args.points <= 0
        or args.top < 0
        or args.tolerance <= 0
        or args.plane_tolerance <= 0
    ):
        print(
            "INVALID OPTIONS: --points must be > 0, "
            "--top >= 0, tolerances must be > 0",
            file=sys.stderr
        )
        return 2

    try:
        args.margins = [
            float(t.strip())
            for t in args.margins.split(",")
        ]

    except ValueError:
        print(
            "INVALID OPTIONS: --margins must be comma-separated numbers",
            file=sys.stderr
        )
        return 2

    if (
        not args.margins
        or any(
            not math.isfinite(v) or v < 0
            for v in args.margins
        )
    ):
        print(
            "INVALID OPTIONS: --margins requires nonnegative finite values",
            file=sys.stderr
        )
        return 2

    pairs = []

    if args.demo:
        pairs += [
            (
                "Partition",
                FIXTURES / "partition_pyfcs.fcs",
                FIXTURES / "partition_jfcs.fcs"
            ),
            (
                "Disjoint_NonCovering",
                FIXTURES / "noncover_pyfcs.fcs",
                FIXTURES / "noncover_jfcs.fcs"
            )
        ]

    if (args.pyfcs is None) != (args.jfcs is None):
        print(
            "INVALID OPTIONS: --pyfcs and --jfcs must be supplied together",
            file=sys.stderr
        )
        return 2

    if args.pyfcs is not None:
        pairs.append(
            ("Single", args.pyfcs, args.jfcs)
        )

    if args.pair:
        pairs += [
            (name, Path(py), Path(java))
            for name, py, java in args.pair
        ]

    # Running directly from VS Code uses the bundled reference pairs.
    if not pairs:
        print(
            "No FCS pair specified: comparing the two bundled example pairs.",
            flush=True
        )

        pairs = [
            (
                "Partition",
                FIXTURES / "partition_pyfcs.fcs",
                FIXTURES / "partition_jfcs.fcs"
            ),
            (
                "Disjoint_NonCovering",
                FIXTURES / "noncover_pyfcs.fcs",
                FIXTURES / "noncover_jfcs.fcs"
            )
        ]

    # Missing inputs are detected before starting the comparison.
    for _, py, java in pairs:
        for p in (py, java):
            if not p.is_file():
                print(
                    f"COMPARISON NOT AVAILABLE: File not found: {p}\n"
                    "Install the FCS fixtures in Source/test/fixtures/ "
                    "or specify --pyfcs and --jfcs.",
                    file=sys.stderr
                )
                return 2

    results = []

    try:
        for name, py, java in pairs:
            print(
                f"Comparing {name} ...",
                flush=True
            )

            result = compare_pair(
                name,
                py,
                java,
                args
            )

            # An incompatible typology is reported without raising an exception.
            if "validation_error" in result:
                print(
                    f"COMPARISON NOT VALID: {result['validation_error']}",
                    file=sys.stderr
                )
                return 2

            results.append(result)

            print(
                "  Identical stored Core/Voronoi/Support planes:",
                "YES" if result["identical_stored_planes"] else "NO",
                flush=True
            )

            for row in result["regions"]:
                print(
                    f"  {row['region']}: "
                    f"Δμ points={row['raw_different_points']}/{row['samples']} "
                    f"({row['raw_different_percent']:.2f}%), "
                    f"max |Δμ|={row['max_raw_membership_difference']:.5f}, "
                    f"mapping winners different={row['mapping_winner_changes']}",
                    flush=True
                )

    except ComparisonInputError as exc:
        print(
            f"COMPARISON NOT VALID: {exc}",
            file=sys.stderr
        )
        return 2

    # Store a JSON summary and the largest discrepancies in CSV.
    args.report_dir.mkdir(
        parents=True,
        exist_ok=True
    )

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

    json_path = (
        args.report_dir
        / f"comparison_{timestamp}.json"
    )

    csv_path = (
        args.report_dir
        / f"comparison_{timestamp}_worst_cases.csv"
    )

    report = {
        "kind": "PyFCS / JFCS FCS saved-geometry comparison",
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "seed": args.seed,
        "points_per_margin": args.points,
        "margins": args.margins,
        "membership_tolerance": args.tolerance,
        "plane_tolerance": args.plane_tolerance,
        "methodology": (
            "Both saved geometries evaluated with PyFCS raw membership; "
            "NOT Java membership execution"
        ),
        "results": results
    }

    json_path.write_text(
        json.dumps(
            report,
            indent=2,
            ensure_ascii=False
        ),
        encoding="utf-8"
    )

    with csv_path.open(
        "w",
        encoding="utf-8",
        newline=""
    ) as f:
        writer = csv.DictWriter(
            f,
            fieldnames=[
                "pair",
                "region",
                "x1",
                "x2",
                "x3",
                "label",
                "mu_pyfcs",
                "mu_jfcs_geometry",
                "absolute_difference",
                "winner_pyfcs",
                "winner_jfcs_geometry"
            ]
        )

        writer.writeheader()

        for result in results:
            for row in result["regions"]:
                for item in row["top_cases"]:
                    writer.writerow({
                        "pair": result["pair"],
                        **item
                    })

    print(
        f"\nJSON report: {json_path}\n"
        f"Worst cases CSV: {csv_path}"
    )

    # Winner differences fail by default; strict flags can also require
    # identical plane sets or memberships.
    if any(
        reg["mapping_winner_changes"]
        for p in results
        for reg in p["regions"]
    ):
        if not args.allow_winner_differences:
            print(
                "FAIL: winner differences detected "
                "(use --allow-winner-differences to report only)"
            )
            return 1

    if args.strict_geometry and any(
        not p["identical_stored_planes"]
        for p in results
    ):
        print(
            "FAIL (strict): stored geometry plane sets are not identical"
        )
        return 1

    if args.strict_membership and any(
        reg["raw_different_points"]
        for p in results
        for reg in p["regions"]
    ):
        print(
            "FAIL (strict): raw memberships are not identical"
        )
        return 1

    print(
        "DONE: compatible configurations; "
        "results quantified (not claimed identical)."
    )

    return 0


if __name__ == "__main__":
    sys.exit(main())
